import { Schema, Connection, Model } from "mongoose";
import bcrypt from "bcryptjs";

const { usersConn } = require("../../server");

interface IUser {
  name: {
    first: string;
    last: string;
  };
  email: string;
  phone: string;
  password: string;
  teamData: {
    id: Schema.Types.ObjectId;
    name: string;
  };
  createdAt: Date;
  updatedAt: Date;
}

// _id property is auto-generated by mongoose
const userSchema = new Schema<IUser>({
  name: {
    // The user's first and last name
    first: { type: String, lowercase: true, trim: true, required: true },
    last: { type: String, lowercase: true, trim: true, required: true },
  },
  email: {
    // The user's email address (Login Credential)
    type: String,
    lowercase: true,
    trim: true,
    unique: true,
    required: true,
  },
  phone: { type: String, unique: true, trim: true, required: true }, // The user's phone number
  password: { type: String, minlength: 8, trim: true, required: true }, // The user's password (Login Credential)
  teamData: {
    id: { type: Schema.Types.ObjectId, unique: true }, // The id of the user's team
    name: { type: String, unique: true }, // The name of the user's team
    // permissionLevel: { type: Number, required: true }, // The user's permission level in the team
  },
  createdAt: { type: Date, default: Date.now() }, // When the user data was created
  updatedAt: { type: Date, default: Date.now() }, // When the user data was last updated
});

// Return user's full name if 'fullName' is requested
userSchema.virtual("fullName").get(function () {
  return this.name.first + " " + this.name.last;
});

// Hash user password before saving user data
userSchema.pre("save", async function (next) {
  const user = this;

  // hash the password if it has been modified (or is new)
  if (user.isModified("password")) {
    const salt = await bcrypt.genSalt(12); // Generate salt
    user.password = await bcrypt.hash(user.password, salt); // Update user.password to hashed value
  }

  next();
});

// Compare password argument to stored password
userSchema.methods.comparePassword = async function (
  password: string,
  callback: Function
) {
  bcrypt.compare(password, this.password, async function (err, isMatch) {
    if (err) return callback(err);
    callback(null, isMatch);
  });
};

const userDb: Connection = usersConn.connection.useDb("users_db");
const User: Model<IUser> = userDb.model("User", userSchema);

module.exports = User;
